package local.skyfamily;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.graphics.Color;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.lang.ref.WeakReference;
public class WeatherKioskActivity extends Activity implements CastService.Presenter {
 static final String URL="https://weatherstar.netbymatt.com/";final Handler timer=new Handler();WebView site;LinearLayout menu;TextView status;boolean failed=false,stopped=false,revealing=false,foreground=false;final Runnable hide=()->{if(!failed)menu.setVisibility(View.GONE);};
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle state){super.onCreate(state);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);site=new WebView(this);root.addView(site,new FrameLayout.LayoutParams(-1,-1));WebSettings settings=site.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(true);settings.setBuiltInZoomControls(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setGeolocationEnabled(false);settings.setMediaPlaybackRequiresUserGesture(true);if(Build.VERSION.SDK_INT>=21)settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);site.setInitialScale(0);site.setWebChromeClient(new WebChromeClient());site.setWebViewClient(Build.VERSION.SDK_INT>=23?new ModernClient():new Client());menu=new LinearLayout(this);menu.setOrientation(1);menu.setBackgroundColor(0xddf2eee6);status=new TextView(this);status.setTextColor(Color.BLACK);status.setPadding(dp(12),dp(4),dp(12),dp(4));menu.addView(status);HorizontalScrollView scroll=new HorizontalScrollView(this);LinearLayout row=new LinearLayout(this);scroll.addView(row);menu.addView(scroll);action(row,"Back",()->finish());action(row,"Reload",()->load());action(row,"Browser",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(URL)));}catch(Exception error){status.setText("Browser unavailable");}});root.addView(menu,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));menu.setVisibility(View.GONE);setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);load();immersive();}
 void action(LinearLayout row,String title,Runnable callback){TextView button=new TextView(this);button.setText(title);button.setTextColor(Color.BLACK);button.setTextSize(16);button.setGravity(Gravity.CENTER);row.addView(button,new LinearLayout.LayoutParams(dp(110),dp(48)));button.setOnClickListener(view->{callback.run();showMenu();});}
 void load(){failed=false;stopped=false;status.setText("WeatherStar 4000+ / location and music controls are on its page");site.loadUrl(URL);}
 void unavailable(){failed=true;status.setText("Weather TV unavailable. Reload or open in browser.");showMenu();}
 void immersive(){getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);int flags=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;if(Build.VERSION.SDK_INT>=19)flags|=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;getWindow().getDecorView().setSystemUiVisibility(flags);}
 void showMenu(){menu.setVisibility(View.VISIBLE);timer.removeCallbacks(hide);timer.postDelayed(hide,3500);}
 public boolean dispatchTouchEvent(MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN&&menu.getVisibility()!=View.VISIBLE){revealing=true;showMenu();}if(revealing){if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)revealing=false;return true;}boolean result=super.dispatchTouchEvent(event);if(action==MotionEvent.ACTION_UP)showMenu();return result;}
 class Client extends WebViewClient{public boolean shouldOverrideUrlLoading(WebView view,String url){return !url.startsWith("https://");}public void onPageFinished(WebView view,String url){if(!failed&&!stopped)status.setText("WeatherStar 4000+ / provider playback not verified");}public void onReceivedError(WebView view,int code,String description,String url){if(url!=null&&url.equals(view.getUrl()))unavailable();}public void onReceivedSslError(WebView view,SslErrorHandler handler,android.net.http.SslError error){handler.cancel();unavailable();}}
 class ModernClient extends Client{public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())unavailable();}public void onReceivedHttpError(WebView view,WebResourceRequest request,WebResourceResponse response){if(request.isForMainFrame()&&response.getStatusCode()>=400)unavailable();}}
 public void showCast(){if(foreground)startActivity(new Intent(this,CastPlayerActivity.class));}
 protected void onResume(){super.onResume();foreground=true;CastService.visible=new WeakReference<CastService.Presenter>(this);site.onResume();if(stopped){status.setText("Weather TV stopped / tap Reload");showMenu();}immersive();}
 protected void onPause(){foreground=false;if(CastService.visible.get()==this)CastService.visible=new WeakReference<CastService.Presenter>(null);timer.removeCallbacksAndMessages(null);stopped=true;site.stopLoading();site.loadUrl("about:blank");site.onPause();super.onPause();}
 protected void onDestroy(){timer.removeCallbacksAndMessages(null);site.destroy();super.onDestroy();}
 public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)immersive();}
 public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);site.requestLayout();immersive();}
}
